-- 跳跃检测线 粗细
local jumpLineRadius = 0.01

-- 跳跃落点 半径
local jumpPointRadius = 0.15
local jumpPointLocalScale = Vector3( jumpPointRadius, jumpPointRadius, jumpPointRadius )

