function CatControllerDebug:__init()
    self.controller = nil

    self.objectsParent = nil
end






function CatControllerDebug:__delete()
end


function CatControllerDebug:Awake()
    KTool.SetActive(self.controller.gameObject, true);

    assert( self.baseCubePrefab and self.baseSpherePrefab  )
    --assert( self.baseCapsulePrefab )


    local luaPrams = KTool.GetComponent(self.controller.gameObject, typeof(LuaParameters))
    assert( luaPrams )

    self.isActive           = LuaParametersReader.Read( luaPrams, "isActive", LuaParametersReader.Type.Bool )

    self.isShowForardLines  = LuaParametersReader.Read( luaPrams, "isShowForardLines", LuaParametersReader.Type.Bool )
    self.isShowUpLines      = LuaParametersReader.Read( luaPrams, "isShowUpLines", LuaParametersReader.Type.Bool )
    self.isShowJumpLedgeLines    = LuaParametersReader.Read( luaPrams, "isShowJumpLedgeLines", LuaParametersReader.Type.Bool )

    self.isShowJumpPoints   = LuaParametersReader.Read( luaPrams, "isShowJumpPoints", LuaParametersReader.Type.Bool )

    self.upColor   = LuaParametersReader.Read( luaPrams, "upColor", LuaParametersReader.Type.Color )
    self.forwardColor   = LuaParametersReader.Read( luaPrams, "forwardColor", LuaParametersReader.Type.Color )
    self.downColor   = LuaParametersReader.Read( luaPrams, "downColor", LuaParametersReader.Type.Color )
    self.moveLedgeColor   = LuaParametersReader.Read( luaPrams, "moveLedgeColor", LuaParametersReader.Type.Color )
    
    self.jumpLedgeColor   = LuaParametersReader.Read( luaPrams, "jumpLedgeColor", LuaParametersReader.Type.Color ) -- _jumpForwardLandPos
    self.jumpLedgeDetectFailureColor = Color.Lerp(self.jumpLedgeColor, Color.black, 0.6) -- 检测失败时的颜色, 更黑一点

    self.forwardDetectColor   = LuaParametersReader.Read( luaPrams, "forwardDetectColor", LuaParametersReader.Type.Color ) -- _jumpForwardDownDetectPos

    self.jumpPointSphereColor   = LuaParametersReader.Read( luaPrams, "jumpPointSphereColor", LuaParametersReader.Type.Color ) -- 透明度要低


    -- ===================================================================
    if self.isActive == false then 
        return
    end

    self.elements = {} -- { nameStr, Transform} 

    -- 上跳射线:
    local bigType = "up"
    local tgtColor = self.upColor
    self:CreateLineGroup1( bigType, "Left2", 2, tgtColor )
    self:CreateLineGroup1( bigType, "Left1", 2, tgtColor )
    self:CreateLineGroup1( bigType, "Mid", 2, tgtColor )
    self:CreateLineGroup1( bigType, "Right1", 2, tgtColor )
    self:CreateLineGroup1( bigType, "Right2", 2, tgtColor )

    -- 前跳射线:
    bigType = "forward"
    tgtColor = self.forwardColor
    self:CreateLineGroup1( bigType, "Left2", 2, tgtColor )
    self:CreateLineGroup1( bigType, "Left1", 2, tgtColor )
    self:CreateLineGroup1( bigType, "Mid", 2, tgtColor )
    self:CreateLineGroup1( bigType, "Right1", 2, tgtColor )
    self:CreateLineGroup1( bigType, "Right2", 2, tgtColor )

    
    -- 下跳射线:
    tgtColor = self.downColor
    self.elements[ "down_1" ]      = self:CreateNewPrimitive(  "down_1",      ShowType.Cube, tgtColor )
    self.elements[ "down_2" ]      = self:CreateNewPrimitive(  "down_2",      ShowType.Cube, tgtColor )

    -- 边缘检测射线:
    self.elements[ "moveLedge_1" ] = self:CreateNewPrimitive(  "moveLedge_1",  ShowType.Cube, self.moveLedgeColor )

    self.elements[ "jumpLedge_1" ] = self:CreateNewPrimitive(  "jumpLedge_1",  ShowType.Cube, self.jumpLedgeColor ) -- 边缘检测, 猫头前向下打的射线
    self.elements[ "jumpLedge_2" ] = self:CreateNewPrimitive(  "jumpLedge_2",  ShowType.Cube, self.jumpLedgeColor ) -- 为计算 _jumpForwardLandPos, 而从猫向 前跳点 打的射线


    -- 检测猫脚下的地面:
    self.elements[ "land_1" ] = self:CreateNewPrimitive(  "land_1",  ShowType.Cube, Color.green )

    -- 从猫前射向 跳跃点, 看看中间是否有遮挡
    self:CreateLineGroup1( "occlusionDetect", "Up", 2, Color.yellow )
    self:CreateLineGroup1( "occlusionDetect", "Down", 2,  Color.yellow )
    self:CreateLineGroup1( "occlusionDetect", "Forward", 3,  Color.yellow )



    self.elements[ "moveDir" ] = self:CreateNewPrimitive( "moveDir", ShowType.Cube,  Color.red )
    self.elements[ "CharacterForward" ] = self:CreateNewPrimitive( "CharacterForward", ShowType.Cube,  Color.green )

    self.elements[ "Oth1" ] = self:CreateNewPrimitive( "Oth1", ShowType.Cube,  Color.yellow )
    self.elements[ "Oth2" ] = self:CreateNewPrimitive( "Oth2", ShowType.Cube,  Color.green )


    -- ======== 胶囊体:
    self:CreateCapsule( "UpCapsule_src", self.upColor )
    self:CreateCapsule( "UpCapsule_dst", self.upColor )


    -- ======== 点: 

    -- 上跳/前跳/下跳 落点: 
    self.elements[ "upPoint" ]                 = self:CreateNewPrimitive(  "upPoint",      ShowType.Sphere, self.upColor )
    self.elements[ "forwardPoint" ]            = self:CreateNewPrimitive(  "forwardPoint", ShowType.Sphere, self.forwardColor )
    self.elements[ "downPoint" ]               = self:CreateNewPrimitive(  "downPoint",    ShowType.Sphere, self.downColor )
    -- _jumpForwardDownDetectPos
    self.elements[ "forwardDetectPoint" ]      = self:CreateNewPrimitive(  "forwardDetectPoint",    ShowType.Sphere, self.forwardDetectColor )

    -- 猫鼻子前
    self.elements[ "headFrontPoint" ]           = self:CreateNewPrimitive(  "headFrontPoint",    ShowType.Sphere, Color.yellow )

    self.elements[ "othPoint_1" ]               = self:CreateNewPrimitive(  "othPoint_1",      ShowType.Sphere, Color.black )

    -- 跳跃落点上方的 空间检测球
    self.elements[ "jumpPointSphere" ]         = self:CreateNewPrimitive(  "jumpPointSphere",  ShowType.Sphere, self.jumpPointSphereColor )

    -- 检测落点所在平台足够 宽(深), 不至于猫跳上去后就从平台边缘滑落下来
    self.elements[ "jumpPlatformDeepDetect" ]  = self:CreateNewPrimitive(  "jumpPlatformDeepDetect",    ShowType.Cube, self.upColor )

end



function CatControllerDebug:OnDestroy()

    self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
    self:Delete()
end





