-- bigType_:  "forward"
-- lineType_: "Left1"
function CatControllerDebug:CreateLineGroup1( bigType_, lineType_, num_, color_ )
    local num = DreamSpaceLuaUtils.NumderToInt(num_)
    for i=1,num do 

        local name = bigType_ .. lineType_ .. "_" .. tostring(i)
        self.elements[ name ] = self:CreateNewPrimitive( name, ShowType.Cube,  color_ )
    end
end




function CatControllerDebug:CreateCapsule( name_, color_ )
    local sphereName1 = name_ .. "_Sphere_1"
    local sphereName2 = name_ .. "_Sphere_2"
    local bodyName    = name_ .. "_body"

    self.elements[ sphereName1 ] = self:CreateNewPrimitive( sphereName1, ShowType.Sphere, color_ )
    self.elements[ sphereName2 ] = self:CreateNewPrimitive( sphereName2, ShowType.Sphere, color_ )
    self.elements[ bodyName ] = self:CreateNewPrimitive( bodyName,       ShowType.Cube, color_ )
end





-- 新建个 杆子 / 球
function CatControllerDebug:CreateNewPrimitive( name_, type_, color_ )

    if self.objectsParent == nil then 
        self.objectsParent = GameObject( "__DreamSpace_Debugs__" ).transform
    end

    local newTF = nil -- Transform
    if type_ == ShowType.Cube then 
        newTF = Object.Instantiate( self.baseCubePrefab )
    elseif type_ == ShowType.Sphere then
        newTF = Object.Instantiate( self.baseSpherePrefab )
    elseif type_ == ShowType.Capsule then
        newTF = Object.Instantiate( self.baseCubePrefab )
    else
        assert( false )
    end

    assert( newTF )
    local newgo = newTF.gameObject
    newTF:SetParent( self.objectsParent )

    newgo.name = name_
    VisualDebugUtils.SetGameObjectColor(newgo, color_)
    local collider = KTool.GetComponent(newgo, typeof(Collider))
    Object.Destroy( collider )
    newTF.localScale = Vector3( 0.2, 0.2, 0.2 )
    newTF.position = infinityFarPos
    return newTF
end



local farPos1 = Vector3( 3000, 0, 0 )
local farPos2 = Vector3( 3001, 0, 0 )
function CatControllerDebug:HideLine( bigType_, lineType_  ) 
    VisualDebugUtils.DrawCubePole( self.elements[ bigType_ .. lineType_ .. "_1" ], farPos1, farPos2, 0.01 )
    VisualDebugUtils.DrawCubePole( self.elements[ bigType_ .. lineType_ .. "_2" ], farPos1, farPos2, 0.01 )
end

