-- [-通用-]: 显示单条射线: 
function CatControllerDebug:UpdateSingleLine( name_, pos1_, pos2_, radius_ ) 
    if self.isActive == false then 
        return
    end
    ---
    if radius_ == nil then 
        radius_ = 0.02
    end
    VisualDebugUtils.DrawCubePole( self.elements[ name_ ], pos1_, pos2_, radius_ ) 
end


-- [-通用-]: 显示单个 capsule: 
function CatControllerDebug:UpdateSingleCapsule( name_, pos1_, pos2_, radius_ ) 
    if self.isActive == false then 
        return
    end
    ---
    -- 暂时先用 cube 来代替...

    local sphereName1 = name_ .. "_Sphere_1"
    local sphereName2 = name_ .. "_Sphere_2"
    local bodyName    = name_ .. "_body"

    local r = radius_ * 2 -- !!! 注意此处的 localScale 应该是 球 radius 的两倍...

    self.elements[sphereName1].position = pos1_
    self.elements[sphereName1].localScale = Vector3( r,r,r )

    self.elements[sphereName2].position = pos2_
    self.elements[sphereName2].localScale = Vector3( r,r,r )

    VisualDebugUtils.DrawCubePole( self.elements[ bodyName ], pos1_, pos2_, r ) 
end


-- [-通用-]: 显示一个点:
function CatControllerDebug:UpdateSinglePoint( name_, pos_, radius_ ) 
    if self.isActive == false then 
        return
    end
    local r = radius_ * 2 -- !!! 注意此处的 localScale 应该是 球 radius 的两倍...
    self.elements[name_].position = pos_
    self.elements[name_].localScale = Vector3( r,r,r )
end


