-- 显示 上跳/前跳 检测射线:
function CatControllerDebug:UpdateForwardOrUpLines( bigType_, lineType_, originTopPos, dir, forwardDistance, downDistance )
    if self.isActive == false then 
        return
    end
    if bigType_ == "forward" then 
        if self.isShowForardLines == false then 
            return
        end
    elseif bigType_ == "up" then
        if self.isShowUpLines == false then 
            return
        end
    end
    ---
    local pos1 = originTopPos
    local pos2 = pos1 + (dir * forwardDistance)
    local pos3 = pos2 + ( Vector3.down * downDistance )
    VisualDebugUtils.DrawCubePole( self.elements[ bigType_ .. lineType_ .. "_1" ], pos1, pos2, jumpLineRadius )
    VisualDebugUtils.DrawCubePole( self.elements[ bigType_ .. lineType_ .. "_2" ], pos2, pos3, jumpLineRadius )
end




-- 显示 边缘检测-跳跃 检测射线 2:
function CatControllerDebug:UpdateJumpLedgeLine_2( pos1_, pos2_, isHit ) 
    if self.isActive == false or self.isShowJumpLedgeLines == false then 
        return
    end
    ---

    local tgtCubeTF = self.elements["jumpLedge_2"]

    VisualDebugUtils.SetGameObjectColor( tgtCubeTF.gameObject, (isHit==true) and self.jumpLedgeColor or self.jumpLedgeDetectFailureColor )

    VisualDebugUtils.DrawCubePole( tgtCubeTF, pos1_, pos2_, 0.02 ) 
end









-- 检测跳跃路径是否被 别的物体遮挡 的射线
function CatControllerDebug:UpdateOcclusionLines( lineType_, pos1, pos2, pos3, pos4 )
    if self.isActive == false then 
        return
    end
    ---
    VisualDebugUtils.DrawCubePole( self.elements[ "occlusionDetect" .. lineType_ .. "_1" ], pos1, pos2, 0.016 )
    VisualDebugUtils.DrawCubePole( self.elements[ "occlusionDetect" .. lineType_ .. "_2" ], pos2, pos3, 0.016 )

    if pos4 ~= nil then 
        VisualDebugUtils.DrawCubePole( self.elements[ "occlusionDetect" .. lineType_ .. "_3" ], pos3, pos4, 0.016 )
    end
end



-- 显示 跳跃 _jumpForwardDownDetectPos 点:
function CatControllerDebug:UpdateJumpForwardDetectPoint( pos_ ) 
    if self.isActive == false or self.isShowJumpPoints == false then 
        return
    end
    self.elements["forwardDetectPoint"].position = pos_
    self.elements["forwardDetectPoint"].localScale =  Vector3( jumpPointLocalScale.x+0.03, jumpPointLocalScale.y+0.03, jumpPointLocalScale.z+0.03 )
end


-- 显示 猫鼻子 点:
function CatControllerDebug:UpdateHeadFrontPoint( pos_, radius_ ) 
    if self.isActive == false then 
        return
    end
    self.elements["headFrontPoint"].position = pos_
    self.elements["headFrontPoint"].localScale = Vector3( radius_,radius_,radius_ )
end



return CatControllerDebug
